@extends('layouts.app') @section('title',$activity->title) @section('content')<div class="pagehead"><div><div class="eyebrow">Activity details</div><h1>{{ $activity->title }}</h1><div class="muted">{{ $activity->course->code }} · {{ $activity->course->title }}</div></div><a class="btn secondary" href="{{ route('activities.index') }}">← All activities</a></div><div class="detailgrid"><section><div class="card"><div class="stats"><div class="stat"><small>Maximum points</small><strong>{{ $activity->max_points }}</strong></div><div class="stat"><small>Due date</small><strong style="font-size:16px">{{ $activity->due_date->format('M d, Y') }}</strong><small>{{ $activity->due_date->format('h:i A') }}</small></div><div class="stat"><small>Submissions</small><strong>{{ $activity->submissions->count() }}</strong></div></div><h2>Instructions</h2><div style="white-space:pre-line">{{ $activity->description }}</div></div><div class="card"><h2 style="margin-top:0">Submitted work</h2>@forelse($activity->submissions as $submission)<div class="item"><strong>{{ $submission->student->full_name }}</strong><div class="muted" style="font-size:12px">{{ $submission->student->student_number }} · submitted {{ $submission->submitted_at->format('M d, Y h:i A') }}</div><p style="white-space:pre-line;margin-bottom:0">{{ $submission->submission_text }}</p>@if($submission->score!==null)<span class="pill green">Score: {{ $submission->score }}/{{ $activity->max_points }}</span>@endif</div>@empty<div class="empty">No submissions recorded yet.</div>@endforelse</div></section><aside class="card"><h2 style="margin-top:0">Record a submission</h2>@if($pendingStudents->count())<form action="{{ route('activities.submit',$activity) }}" method="POST">@csrf<div class="field"><label for="student_id">Enrolled student</label><select id="student_id" name="student_id" required><option value="">Choose a student</option>@foreach($pendingStudents as $student)<option value="{{ $student->id }}" @selected(old('student_id'